// ViewBox crops to just the gold M+handshake instance from the SVG
const VB_X = 725, VB_Y = 0, VB_W = 380, VB_H = 442;

export default function MoneySymbol({ size = 16, color = '#D4AF37', style, progress }) {
  const aspectRatio = VB_W / VB_H;
  const w = size * aspectRatio;
  const h = size;

  // ── Forge mode: reveal bottom-to-top in quarters (progress 0→1) ──────────
  // A faint ghost of the full logo is always visible beneath the revealed part,
  // so the user can see what's being forged even before it's fully unlocked.
  if (progress !== undefined && progress < 1) {
    const p     = Math.max(0, Math.min(1, progress));
    const clipY = VB_Y + VB_H * (1 - p);   // clip rect starts higher as p grows
    const clipH = VB_H * p;                  // clip rect height = revealed portion

    return (
      <View style={[{ width: w, height: h }, style]}>
        <Svg width={w} height={h} viewBox={`${VB_X} ${VB_Y} ${VB_W} ${VB_H}`}>
          <Defs>
            <ClipPath id="fc">
              <Rect x={VB_X} y={clipY} width={VB_W} height={Math.max(0, clipH)} />
            </ClipPath>
          </Defs>
          {/* Ghost: full logo at very low opacity — shows what is still locked */}
          <Path d={PATH} fill={color} opacity={0.09} />
          {/* Revealed portion: solid gold, grows bottom-to-top with each strike */}
          <Path d={PATH} fill={color} clipPath="url(#fc)" />
        </Svg>
      </View>
    );
  }

  // ── Normal mode ───────────────────────────────────────────────────────────
  return (
    <View style={[{ width: w, height: h }, style]}>
      <Svg width={w} height={h} viewBox={`${VB_X} ${VB_Y} ${VB_W} ${VB_H}`}>
        <Path d={PATH} fill={color} />
      </Svg>
    </View>
  );
}
